func refMatch(pattern, path string) bool {
	// pattern always starts with '/'
	ps := strings.Split(pattern, "/")   // for "/a/:b" -> ["", "a", ":b"]
	ts := strings.Split(path, "/")
	// match recursively
	var m func(i, j int) bool
	m = func(i, j int) bool {
		if i == len(ps) {
			return j == len(ts)
		}
		if ps[i] == "*" {
			return true // matches rest, including empty
		}
		if j == len(ts) {
			return false
		}
		if ps[i] == "" || ps[i][0] != ':' {
			if ps[i] != ts[j] { return false }
		} else if ts[j] == "" {
			return false
		}
		return m(i+1, j+1)
	}
	return m(0, 0)
}
