		h := c.Handler()
		res = fmt.Sprintf("handler=%p path=%q pnames=%v", h, c.Path(), c.ParamNames())
	}()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
		timedOut = true
	}
	return
