func genPattern(rnd *rand.Rand) string {
	n := rnd.Intn(4)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch rnd.Intn(6) {
		case 0:
			segs = append(segs, "a")
		case 1:
			segs = append(segs, "b")
		case 2:
			segs = append(segs, "ab")
		case 3:
			segs = append(segs, ":p")
		case 4:
			segs = append(segs, ":q")
		case 5:
			segs = append(segs, "*")
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(10) == 0 {
		p = p + "/"
	}
	if rnd.Intn(20) == 0 {
		p = p[1:] // no leading slash
	}
	if rnd.Intn(30) == 0 {
		p = ""
	}
	return p
}

func genPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		switch rnd.Intn(5) {
		case 0:
			segs = append(segs, "a")
		case 1:
			segs = append(segs, "b")
		case 2:
			segs = append(segs, "ab")
		case 3:
			segs = append(segs, "")
		case 4:
			segs = append(segs, "x")
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(10) == 0 {
		p = p[1:]
	}
	if rnd.Intn(20) == 0 {
		p = ""
	}
	return p
}

func TestFz2(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	methods := []string{http.MethodGet, http.MethodPost}
	for iter := 0; iter < 20000; iter++ {
		e := New()
		var routes []string
		n := 1 + rnd.Intn(5)
		for i := 0; i < n; i++ {
			p := genPattern(rnd)
			m := methods[rnd.Intn(len(methods))]
			routes = append(routes, m+" "+p)
			e.router.Add(m, p, func(c Context) error { return nil })
		}
		for i := 0; i < 6; i++ {
			path := genPath(rnd)
			m := methods[rnd.Intn(len(methods))]
			done := make(chan string, 1)
			var panicked interface{}
			go func() {
				defer func() {
					if r := recover(); r != nil {
						panicked = r
					}
					done <- "x"
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(m, path, c)
				c.Handler()
			}()
			select {
			case <-done:
			case <-time.After(2 * time.Second):
				t.Fatalf("TIMEOUT routes=%v find=%s %q", routes, m, path)
			}
			if panicked != nil {
				t.Fatalf("PANIC routes=%v find=%s %q: %v", routes, m, path, panicked)
			}
		}
	}
}

func TestFz2Print(t *testing.T) {
	fmt.Println("ok")
}
