	if !reflect.DeepEqual(destSlice, wantSlice) {
		t.Fatalf("map[string][]string = %#v, want %#v", destSlice, wantSlice)
	}
	t.Logf("map[string][]string ok: %#v", destSlice)

	// 2) direct bindData into map[string]interface{}: unchanged behaviour (first value, as string)
	destIface := map[string]interface{}{}
	if err := b.bindData(&destIface, data, "query"); err != nil {
		t.Fatalf("bindData(map[string]interface{}) error = %v", err)
	}
