		t.Fatalf("Bind(map[string]interface{}) error = %v", err)
	}
	if !reflect.DeepEqual(viaBindIface, wantIface) {
		t.Fatalf("Bind map[string]interface{} = %#v, want %#v", viaBindIface, wantIface)
	}
	t.Logf("Bind map[string]interface{} ok: %#v", viaBindIface)
}

