			*bad++
			t.Errorf("label mismatch routes=%v", routes)
		}
		if c.parent != n {
			*bad++
			t.Errorf("parent mismatch routes=%v", routes)
		}
		checkInv(t, c, path, bad, routes)
	}
	if n.paramChild != nil {
		if n.paramChild.kind != paramKind {
			*bad++
			t.Errorf("paramChild kind=%d routes=%v", n.paramChild.kind, routes)
		}
		checkInv(t, n.paramChild, path, bad, routes)
	}
	if n.anyChild != nil {
		if n.anyChild.kind != anyKind {
