			t.Errorf("anyChild kind=%d routes=%v", n.anyChild.kind, routes)
		}
		checkInv(t, n.anyChild, path, bad, routes)
	}
}

func TestInv(t *testing.T) {
	rnd := rand.New(rand.NewSource(31337))
