func dump(t *testing.T, name string, rec *httptest.ResponseRecorder) {
	t.Helper()
	body := rec.Body.Bytes()
	fmt.Printf("=== %s\n  code=%d liveHdr=%v\n  resultHdr=%v\n  bodyLen=%d body=%q\n", name, rec.Code, rec.Header(), rec.Result().Header, len(body), body)
	if len(body) > 0 {
		r, err := gzip.NewReader(bytes.NewReader(body))
		if err != nil {
			fmt.Printf("  gzip.NewReader err: %v\n", err)
		} else {
			b, err := ioutil.ReadAll(r)
			fmt.Printf("  decompressed=%q err=%v\n", b, err)
			_ = r.Close()
		}
	}
}

func TestTmpGzipEmptyDiag(t *testing.T) {
	scenarios := []struct {
		name string
		h    echo.HandlerFunc
	}{
		{"write-empty-slice", func(c echo.Context) error { _, err := c.Response().Write([]byte{}); return err }},
		{"write-empty-string", func(c echo.Context) error { return c.String(http.StatusOK, "") }},
		{"nothing-at-all", func(c echo.Context) error { return nil }},
		{"no-content-200", func(c echo.Context) error { return c.NoContent(http.StatusOK) }},
		{"writeheader-200-only", func(c echo.Context) error { c.Response().WriteHeader(http.StatusOK); return nil }},
		{"flush-empty", func(c echo.Context) error { c.Response().Flush(); return nil }},
		{"write-empty-then-flush", func(c echo.Context) error { c.Response().Write([]byte{}); c.Response().Flush(); return nil }},
		{"blob-empty", func(c echo.Context) error { return c.Blob(http.StatusOK, "text/plain", []byte{}) }},
	}
	for _, s := range scenarios {
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(s.h)
		err := h(c)
		dump(t, s.name, rec)
		fmt.Printf("  handlerErr=%v\n", err)
	}
	// Also via full ServeHTTP (real server path)
	for _, s := range scenarios {
		e := echo.New()
		e.Use(Gzip())
		e.GET("/", s.h)
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		dump(t, "ServeHTTP/"+s.name, rec)
	}
}

