// lenient: params may match empty segments; '*' consumes the rest (needs at least the trailing empty segment)
func lenientMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	var m func(i, j int) bool
	m = func(i, j int) bool {
		if i == len(ps) {
			return j == len(xs)
		}
		seg := ps[i]
		if seg == "*" {
			return j < len(xs)
		}
		if j >= len(xs) {
			return false
		}
		if strings.HasPrefix(seg, ":") {
			return m(i+1, j+1)
		}
		if seg == xs[j] {
			return m(i+1, j+1)
		}
		return false
	}
	return m(0, 0)
}

