package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
)

type chainLog struct {
	labels []string
}

func (cl *chainLog) mw(name string) MiddlewareFunc {
	return func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			cl.labels = append(cl.labels, name)
			return next(c)
		}
	}
}

func (cl *chainLog) h(name string) HandlerFunc {
	return func(c Context) error {
		cl.labels = append(cl.labels, name)
		return c.NoContent(200)
	}
}

type expEntry struct {
	chain []string
	code  int
}

func normPath(p string) string {
	if p == "" {
		return "/"
	}
	if p[0] != '/' {
		return "/" + p
	}
	return p
}

func TestRandomGroupMiddleware2(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	prefixes := []string{"/group", "/g1", "/g2", "", "/"}
	subPaths := []string{"", "/a", "/b", "/route", "/a/b"}
	methods := []string{http.MethodGet, http.MethodPost}
	hosts := []string{"", "a.com", "b.com"}
	bad := 0
	for iter := 0; iter < 600; iter++ {
		cl := &chainLog{}
		e := New()
		type grp struct {
			g    *Group
			mw   []string
			host string
		}
		var groups []*grp
		expect := map[string]expEntry{}
		nGroups := 2 + rnd.Intn(2)
		for i := 0; i < nGroups; i++ {
			h := hosts[rnd.Intn(len(hosts))]
			var g *Group
			if h != "" {
				g = e.Host(h)
			} else {
				g = &Group{echo: e}
			}
			groups = append(groups, &grp{g: g, host: h})
		}
		nOps := 6 + rnd.Intn(12)
		for op := 0; op < nOps; op++ {
			gi := rnd.Intn(len(groups))
			gr := groups[gi]
			switch rnd.Intn(4) {
			case 0: // Use
				label := fmt.Sprintf("u%d_%d", gi, op)
				gr.mw = append(gr.mw, label)
				gr.g.Use(cl.mw(label))
				for _, m := range methods {
					for _, p := range []string{normPath(gr.g.prefix), normPath(gr.g.prefix + "/*")} {
						expect[gr.host+"|"+m+" "+p] = expEntry{chain: append([]string{}, gr.mw...), code: 404}
					}
				}
			case 1: // sub-group
				sp := prefixes[rnd.Intn(len(prefixes))]
				sg := gr.g.Group(sp)
				groups = append(groups, &grp{g: sg, mw: append([]string{}, gr.mw...), host: gr.host})
			case 2, 3: // route
				sp := subPaths[rnd.Intn(len(subPaths))]
				m := methods[rnd.Intn(len(methods))]
				hl := fmt.Sprintf("h%d_%d", gi, op)
				chain := append([]string{}, gr.mw...)
				if rnd.Intn(2) == 0 {
					rl := fmt.Sprintf("r%d_%d", gi, op)
					chain = append(chain, rl)
					gr.g.Add(m, sp, cl.h(hl), cl.mw(rl))
				} else {
					gr.g.Add(m, sp, cl.h(hl))
				}
				key := gr.host + "|" + m + " " + normPath(gr.g.prefix+sp)
				expect[key] = expEntry{chain: append(chain, hl), code: 200}
			}
		}
		keys := make([]string, 0, len(expect))
		for k := range expect {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		// two passes to catch state-dependent behaviour
		for pass := 0; pass < 2; pass++ {
			for _, k := range keys {
				if strings.ContainsAny(k, "*:") {
					continue
				}
				parts := strings.SplitN(k, "|", 2)
				host, mp := parts[0], parts[1]
				mparts := strings.SplitN(mp, " ", 2)
				m, p := mparts[0], mparts[1]
				cl.labels = nil
				req := httptest.NewRequest(m, p, nil)
				req.Host = host
				rec := httptest.NewRecorder()
				e.ServeHTTP(rec, req)
				got := strings.Join(cl.labels, ",")
				want := strings.Join(expect[k].chain, ",")
				if got != want || rec.Code != expect[k].code {
					bad++
					if bad < 15 {
						fmt.Printf("MISMATCH iter=%d pass=%d req=%s host=%q %s got=[%s] code=%d want=[%s] code=%d\n", iter, pass, m, host, p, got, rec.Code, want, expect[k].code)
					}
				}
			}
		}
	}
	fmt.Println("total mismatches:", bad)
}
EOF
